const state={gear:[],goals:[],plans:[],planning:{batches:[]},powerRange:'all',powerType:'all',powerFrom:'',powerTo:'',compareAnalysis:{},page:'calendar',month:new Date(2026,10,16,12),view:'calendar',activities:[],workouts:[],settings:{},wellness:[],fitness:[],power:{curve:[],zones:[]},query:'',type:'all',showPlanned:true,compact:false,library:false,compareIds:[],dark:localStorage.getItem('cycle-dark')==='true'};
document.body.classList.toggle('dark',state.dark);
const today=()=>dateKey(new Date());
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function parseDate(s){return new Date(`${s}T12:00:00`);}
function addDays(s,n){const d=parseDate(s);d.setDate(d.getDate()+n);return dateKey(d);}
function duration(n){n=Number(n)||0;if(n>0&&n<1)return `${Math.round(n*60)}s`;n=Math.round(n);return n>=60?`${Math.floor(n/60)}h${n%60?String(n%60).padStart(2,'0')+'m':''}`:`${n}m`;}
const sum=(items,key)=>items.reduce((s,a)=>s+(Number(a[key])||0),0);
function num(n,d=0){return Number.isFinite(Number(n))?Number(n).toLocaleString('zh-CN',{maximumFractionDigits:d}):'—';}
async function api(path,method='GET',body){const r=await fetch(`/api${path}`,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json();}catch{throw new Error('服务返回了无法读取的数据');}if(!r.ok)throw Object.assign(new Error(data.error||'操作失败'),{status:r.status,code:data.code});return data;}
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
function error(e){console.error(e);toast(e.message||String(e));}
async function refresh(){[state.activities,state.workouts,state.settings,state.gear,state.goals]=await Promise.all([api('/activities'),api('/workouts'),api('/settings'),api('/gear'),api('/goals?asOf='+today())]);if(state.page==='power')await loadPower();if(state.page==='compare')await loadCompare();if(state.page==='plans')await planningTools.load();}
function logo(){return `<svg viewBox="0 0 32 32" fill="none"><rect x="2" y="20" width="5" height="10" rx="1" fill="#1976d2"/><rect x="10" y="13" width="5" height="17" rx="1" fill="#1976d2"/><rect x="18" y="3" width="5" height="27" rx="1" fill="#1976d2"/><rect x="26" y="9" width="4" height="21" rx="1" fill="#82b6e7"/></svg>`;}
function shell(){const current=navItems.find(n=>n[0]===state.page);$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${logo()}Cycle<small>LOCAL</small></div><div class="athlete"><div class="avatar">${esc((state.settings.name||'本')[0])}</div><div><span>${esc(state.settings.name||'本地运动员')}</span><div class="tiny">个人训练空间</div></div></div><div class="nav-label">训练与分析</div><nav class="nav">${navItems.map(([p,title,i],j)=>`${p==='settings'?'<div class="nav-gap"></div><div class="nav-label">工作空间</div>':''}<button data-nav="${p}" class="${state.page===p?'active':''}">${icon(i)}${title}</button>`).join('')}</nav><div class="sidebar-foot"><span class="local-dot"></span>本机存储 · 离线可用<p>你的训练，属于你自己。<br>Cycle v1.0.0</p></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="打开菜单">${icon('menu')}</button><span class="hide-mobile">个人工作空间</span><span class="hide-mobile">/</span><strong>${current[1]}</strong></div><div class="top-actions"><span class="pill"><span class="local-dot"></span>本地模式</span><button class="icon-btn" data-action="dark" aria-label="切换深浅主题" title="切换深浅主题">${icon('moon')}</button><button class="icon-btn" data-action="help" aria-label="使用说明" title="使用说明">${icon('help')}</button><div class="avatar" style="width:28px;height:28px;font-size:11px">${esc((state.settings.name||'本')[0])}</div></div></header>${state.activities.some(a=>a.demo)?'<div class="demo-banner"><span>当前包含演示记录 · 用于体验本地功能</span><button data-action="clear-demo">清除演示记录</button></div>':''}<div class="content" id="content"></div></main></div>`;renderPage();}
function heading(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function empty(title,text,action='',i='calendar'){return `<div class="empty">${icon(i)}<strong>${title}</strong><p>${text}</p><div class="actions">${action}</div></div>`;}
function btn(text,action,i='plus',primary=false,extra=''){return `<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${icon(i)}${text}</button>`;}
function stat(label,value,unit,note,i){return `<div class="summary-item"><div><div class="stat-label">${label}</div><div class="stat-number">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div><div class="summary-icon">${icon(i)}</div></div>`;}
function monthActivities(){const key=dateKey(state.month).slice(0,7);return state.activities.filter(a=>a.date.startsWith(key));}
function filtered(items){return items.filter(a=>(state.showPlanned||!a.planned)&&(state.type==='all'||a.type===state.type)&&(!state.query||`${a.name} ${a.notes||''}`.toLowerCase().includes(state.query.toLowerCase())));}
function miniChart(a){let values=a.intervals?.length?a.intervals.map(x=>({value:Number(x.power)||0,end:x.powerEnd??x.power,width:Number(x.duration)||1})):[];if(!values.length&&effectiveUIStreams(a).some(x=>x.power>0)){const stream=effectiveUIStreams(a);const step=Math.max(1,Math.floor(stream.length/36));values=stream.filter((_,i)=>i%step===0).slice(0,60).map(x=>({value:Number.isFinite(x.power)?x.power/(resolveFtp(a,state.settings).ftp||250)*100:null,width:1}));}if(!values.length)return '';const width=values.reduce((s,x)=>s+x.width,0);let x=0;return `<svg class="mini-chart" viewBox="0 0 150 40" preserveAspectRatio="none" aria-label="训练功率概览">${values.map(v=>{const w=v.width/width*150;if(v.value===null){x+=w;return '';}const h=Math.max(1,Math.min(v.value/150*38,38));const idx=v.value<=55?0:v.value<=75?1:v.value<=90?2:v.value<=105?3:v.value<=120?4:v.value<=150?5:6;const h2=Math.max(1,Math.min((v.end??v.value)/150*38,38));const r=`<polygon points="${x.toFixed(2)},40 ${x.toFixed(2)},${40-h} ${(x+Math.max(.3,w-.6)).toFixed(2)},${40-h2} ${(x+Math.max(.3,w-.6)).toFixed(2)},40" fill="${zones[idx]}" opacity=".85"/>`;x+=w;return r;}).join('')}</svg>`;}
function activityCard(a){return `<button class="card ${esc(a.type)} ${a.planned?'planned':''}" draggable="true" data-activity="${esc(a.id)}" aria-label="${esc(a.name)}"><div class="card-top">${icon(types[a.type]?.[1]||'note')}<span>${duration(a.duration)}${a.distance?` · ${num(a.distance,1)} km`:''}</span>${a.planned?`<span>${a.completionId?'已关联':'计划'}</span>`:''}</div><div class="card-body"><div class="card-metrics">${a.hr?`<span class="red">${num(a.hr)} bpm</span>`:''}${a.power?`<span class="purple">${num(a.power)} w</span>`:''}</div>${a.type!=='Note'?`<div class="card-metrics">负荷 <b>${num(a.load)}</b></div>`:''}${miniChart(a)}<div class="card-name">${esc(a.name)}</div></div></button>`;}
function calendarView(){const current=monthActivities(),done=current.filter(a=>!a.planned&&a.type!=='Note'), planned=current.filter(a=>a.planned&&!a.completionId);let h=heading('活动','每一次积累，都是下一次进步的起点。',btn('导入活动','import','upload')+btn('添加','add','plus',true));
 if(!state.activities.length)h+=`<div class="welcome"><div><strong>欢迎来到你的本地训练日志</strong><p>导入 FIT / CSV / GPX / TCX 文件，或手动添加一次活动。也可以先载入演示数据，探索整个工作空间。</p></div><div class="actions">${btn('体验演示数据','demo','power')}${btn('导入活动','import','upload',true)}</div></div>`;
 h+=`<div class="summary-strip">${stat('本月训练时间',duration(sum(done,'duration')),'',`${done.length} 次已完成活动`,'clock')}${stat('累计距离',num(sum(done,'distance'),1),'km','本月已完成活动','distance')}${stat('训练负荷',num(sum(done,'load')),'',`计划负荷 ${num(sum(planned,'load'))}`,'fitness')}${stat('计划完成',done.length,'次',`${planned.length} 次待完成计划`,'check')}</div>`;
 h+=`<section class="calendar-panel"><div class="calendar-tools"><div class="month-switch"><button class="icon-btn" data-action="prev" aria-label="上个月">${icon('left')}</button><strong>${state.month.getFullYear()} 年 ${state.month.getMonth()+1} 月</strong><button class="icon-btn" data-action="next" aria-label="下个月">${icon('right')}</button><button class="btn small" data-action="today">今天</button></div><div class="actions"><input class="search" id="calendar-search" placeholder="搜索活动…" aria-label="搜索活动" value="${esc(state.query)}"><div class="segmented"><button data-view="calendar" class="${state.view==='calendar'?'active':''}" aria-label="日历视图">${icon('grid')}</button><button data-view="list" class="${state.view==='list'?'active':''}" aria-label="列表视图">${icon('list')}</button></div><button class="btn small" data-action="library">${icon('library')}<span class="hide-mobile">训练库</span></button><button class="icon-btn" data-action="options" aria-label="日历选项">${icon('settings')}</button></div></div><div id="calendar-body">${state.view==='calendar'?calendarGrid():activityTable(filtered(current))}</div><div class="calendar-footer"><div class="legend"><span><i style="background:#1976d2"></i>已完成</span><span><i style="background:#e4ac55"></i>训练计划</span><span><i style="background:#258d77"></i>跑步</span></div><span>拖动活动调整日期 · 双击日期添加活动</span></div></section><div class="footer-note"><span>本机数据库持久保存 · 可在设置中导出完整备份</span><span>Cycle · 本地训练工作空间</span></div>`;return h;}
function calendarGrid(){const first=new Date(state.month.getFullYear(),state.month.getMonth(),1,12),offset=(first.getDay()+6)%7;first.setDate(first.getDate()-offset);const rows=Math.ceil((offset+new Date(state.month.getFullYear(),state.month.getMonth()+1,0).getDate())/7);let html=`<div class="calendar-scroll"><div class="calendar ${state.compact?'compact':''}"><div class="weekdays">${['周一','周二','周三','周四','周五','周六','周日','周汇总'].map(d=>`<div>${d}</div>`).join('')}</div>`;
 for(let w=0;w<rows;w++){const start=dateKey(first),end=addDays(start,6);const week=state.activities.filter(a=>a.date>=start&&a.date<=end&&a.type!=='Note'),done=week.filter(a=>!a.planned);html+='<div class="week">';for(let i=0;i<7;i++){const key=dateKey(first),items=filtered(state.activities.filter(a=>a.date===key));html+=`<div class="day ${first.getMonth()!==state.month.getMonth()?'other':''} ${key===today()?'today':''}" data-date="${key}"><div class="day-head"><span class="date-number">${first.getDate()}</span><button class="add-day" data-add-date="${key}" aria-label="在 ${key} 添加活动">+</button></div>${state.goals.filter(g=>g.date===key).map(g=>`<button class="goal-marker" data-workspace-tool="edit-goal" data-workspace-id="${esc(g.id)}"><span>${g.priority}</span>${esc(g.name)}</button>`).join('')}${items.map(activityCard).join('')}</div>`;first.setDate(first.getDate()+1);}html+=`<div class="week-total"><div class="week-date">${start.slice(5).replace('-','/')} – ${end.slice(5).replace('-','/')}</div><strong class="blue">${duration(sum(done,'duration'))}</strong><strong>${num(sum(done,'distance'),1)} <small>km</small></strong><p>负荷 ${num(sum(done,'load'))}<br>${done.length} 次活动<br>计划 ${duration(sum(week.filter(a=>a.planned&&!a.completionId),'duration'))}</p></div></div>`;}return html+'</div></div>';}
function activityTable(items,select=false){if(!items.length)return empty('还没有活动','导入训练文件，或者添加一条活动记录。',btn('添加活动','add'));return `<div style="overflow-x:auto"><table class="data-table"><thead><tr>${select?'<th>选择</th>':''}<th>活动</th><th>日期</th><th>类型</th><th>时间</th><th>距离</th><th>负荷</th><th>状态</th></tr></thead><tbody>${[...items].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<tr>${select?`<td><input type="checkbox" data-compare-check="${esc(a.id)}" ${state.compareIds.includes(a.id)?'checked':''} aria-label="比较 ${esc(a.name)}"></td>`:''}<td><button class="name-cell" data-activity="${esc(a.id)}">${esc(a.name)}</button></td><td>${esc(a.date)}</td><td>${types[a.type]?.[0]||esc(a.type)}</td><td>${duration(a.duration)}</td><td>${num(a.distance,1)} km</td><td>${num(a.load)}</td><td><span class="badge ${a.planned?'plan':''}">${a.planned?'计划':'已完成'}</span>${a.demo?' <span class="badge demo">演示</span>':''}</td></tr>`).join('')}</tbody></table></div>`;}
const chart=zoomableChart(baseChart);
function baseChart(series,{height=270,xLabels=[],ylabel='',min=undefined,xDomain=null}={}){const all=series.flatMap(s=>s.values).filter(Number.isFinite);if(!all.length)return empty('暂无可绘制数据','导入活动或添加记录后查看趋势。','','fitness');const W=920,H=height,p={l:48,r:20,t:18,b:35};let lo=min??all.reduce((a,b)=>Math.min(a,b),0),hi=all.reduce((a,b)=>Math.max(a,b),-Infinity);if(hi<=lo)hi=lo+1;const Y=v=>p.t+(hi-v)/(hi-lo)*(H-p.t-p.b);const maxLen=Math.max(...series.map(s=>s.values.length)),X=i=>p.l+i/Math.max(1,maxLen-1)*(W-p.l-p.r);let svg=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(ylabel)}趋势图"><text x="8" y="12">${esc(ylabel)}</text>`;for(let i=0;i<=4;i++){const v=lo+(hi-lo)/4*i,y=Y(v);svg+=`<line class="chart-grid" x1="${p.l}" x2="${W-p.r}" y1="${y}" y2="${y}"/><text x="${p.l-10}" y="${y+4}" text-anchor="end">${num(v,hi-lo<1?3:hi-lo<10?2:hi-lo<100?1:0)}</text>`;}
for(const s of series){const points=s.values.map((v,i)=>Number.isFinite(v)?[xDomain&&s.times?p.l+(s.times[i]-xDomain[0])/Math.max(1e-9,xDomain[1]-xDomain[0])*(W-p.l-p.r):X(i),Y(v)]:null);const seg=[];let current=[];for(const pt of points){if(pt)current.push(pt);else if(current.length){seg.push(current);current=[];}}if(current.length)seg.push(current);for(const pts of seg){const line=pts.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');if(s.area)svg+=`<path d="${line} L${pts.at(-1)[0]},${Y(Math.max(lo,0))} L${pts[0][0]},${Y(Math.max(lo,0))} Z" fill="${s.color}" opacity=".09"/>`;svg+=`<path d="${line}" fill="none" stroke="${s.color}" stroke-width="2" stroke-linejoin="round"/>`;if(pts.length===1)svg+=`<circle cx="${pts[0][0]}" cy="${pts[0][1]}" r="3" fill="${s.color}"/>`;}}
if(xDomain){for(let i=0;i<=4;i++){const t=Math.max(0,Math.round(xDomain[0]+(xDomain[1]-xDomain[0])*i/4)),label=`${Math.floor(t/3600)?Math.floor(t/3600)+':':''}${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;svg+=`<text x="${p.l+i/4*(W-p.l-p.r)}" y="${H-10}" text-anchor="middle">${label}</text>`;}}else{const ticks=[...new Set([0,Math.round((maxLen-1)/4),Math.round((maxLen-1)/2),Math.round((maxLen-1)*.75),maxLen-1])];for(const i of ticks)svg+=`<text x="${X(i)}" y="${H-10}" text-anchor="middle">${esc(xLabels[i]??i+1)}</text>`;}return svg+'</svg>';}
function fitnessView(){const data=state.fitness,latest=[...data].reverse().find(d=>d.date<=today())||data.at(-1)||{};return heading('体能','通过已完成训练负荷，观察体能、疲劳与状态的变化。',`<select id="fitness-range" aria-label="趋势时间范围"><option value="90">近 90 天</option><option value="180">近 180 天</option><option value="365">近一年</option></select>`)+`<div class="summary-strip">${stat('体能 · CTL',num(latest.ctl,1),'',`${state.settings.ctlDays||42} 天时间常数`,'fitness')}${stat('疲劳 · ATL',num(latest.atl,1),'',`${state.settings.atlDays||7} 天时间常数`,'power')}${stat('状态 · TSB',num(latest.tsb,1),'','当日训练前的 CTL − ATL','heart')}${stat('最近一天负荷',num(latest.load),'',latest.date||'尚无记录','calendar')}</div><section class="panel"><div class="panel-head"><h2>体能趋势</h2><div class="legend"><span><i style="background:#3a97d4"></i>体能</span><span><i style="background:#9d79bd"></i>疲劳</span><span><i style="background:#e5b85a"></i>状态</span></div></div><div class="chart-wrap">${state.activities.some(a=>!a.planned&&a.load>0)?fitnessChart(data):empty('建立你的体能曲线','添加带训练负荷的已完成活动后，这里会计算并显示趋势。',btn('添加活动','add'),'fitness')}</div><div class="panel-body section-caption">体能与疲劳按已完成训练负荷计算，时间常数和初始值可在设置中调整。</div></section>`;}
function fitnessChart(data){return chart([{values:data.map(d=>d.ctl),color:'#3a97d4',area:true},{values:data.map(d=>d.atl),color:'#9d79bd'},{values:data.map(d=>d.tsb),color:'#e5b85a'}],{xLabels:data.map(d=>d.date.slice(5)),ylabel:'训练负荷'});}
function basicPowerView(){const p=state.power,curve=p.curve||[],z=p.zones||[];return heading('功率','从真实活动采样中，寻找不同持续时间的最佳表现。',btn('导入活动','import','upload'))+`<div class="summary-strip">${stat('当前 FTP',num(state.settings.ftp),'W','在设置中手动配置','power')}${stat('相对功率',num((state.settings.ftp||0)/(state.settings.weight||1),2),'W/kg',`体重 ${num(state.settings.weight,1)} kg`,'fitness')}${stat('最佳 5 分钟',num(curve.find(x=>x.seconds===300)?.watts),'W','来自已导入功率采样','clock')}${stat('最佳 20 分钟',num(curve.find(x=>x.seconds===1200)?.watts),'W','来自已导入功率采样','power')}</div><div class="stack"><section class="panel"><div class="panel-head"><h2>功率持续时间曲线</h2><span class="tiny">全部已完成活动</span></div><div class="chart-wrap">${curve.length?chart([{values:curve.map(x=>x.watts),color:'#8e67b1',area:true}],{xLabels:curve.map(x=>x.seconds<60?`${x.seconds}s`:x.seconds<3600?`${x.seconds/60}m`:`${x.seconds/3600}h`),ylabel:'功率 / W'}):empty('还没有功率采样','导入带功率采样的活动，查看各持续时间的最佳表现。',btn('导入活动','import','upload'),'power')}</div></section><div class="grid-2"><section class="panel"><div class="panel-head"><h2>功率区间分布</h2><span class="tiny">按每次活动生效 FTP</span></div><div class="panel-body">${z.some(x=>x.seconds)?zoneRows(z):empty('暂无区间统计','需要逐点功率数据。','','power')}</div></section><section class="panel"><div class="panel-head"><h2>训练区间参考</h2><span class="tiny">FTP ${num(state.settings.ftp)} W</span></div><div class="panel-body">${zoneReference()}</div></section></div></div>`;}
function zoneRows(z){const total=sum(z,'seconds');return z.map((x,i)=>`<div class="zone-row"><span><i class="inline-color" style="background:${x.color||zones[i]}"></i>${esc(x.name||`Z${i+1}`)}</span><div class="zone-bar"><div style="width:${total?x.seconds/total*100:0}%;background:${x.color||zones[i]}"></div></div><span style="text-align:right">${duration(x.seconds/60)}</span></div>`).join('');}
function zoneReference(){const ftp=state.settings.ftp||250;return [['主动恢复',0,.55],['耐力',.55,.75],['节奏',.75,.9],['乳酸阈',.9,1.05],['VO₂ Max',1.05,1.2],['无氧',1.2,1.5],['神经肌肉',1.5,Infinity]].map(([n,l,h],i)=>`<div class="zone-row"><span><i class="inline-color" style="background:${zones[i]}"></i>Z${i+1} ${n}</span><span class="tiny">${Math.round(l*100)}${h<Infinity?`–${Math.round(h*100)}`:'+'}% FTP</span><span style="text-align:right">${Math.round(l*ftp)}${h<Infinity?`–${Math.round(h*ftp)}`:'+'} W</span></div>`).join('');}
function workoutsView(){return heading('训练库','把训练结构保存下来，为下一次出发做好准备。',btn('新建训练','new-workout','plus',true))+`<p class="section-caption">训练支持重复组、秒级步骤和渐变功率，保存前可实时预览。骑行功率训练可导出 ZWO 文件。</p>${state.workouts.length?`<div class="grid-3">${state.workouts.map(w=>`<article class="workout-card" draggable="true" data-workout="${esc(w.id)}"><div class="actions" style="justify-content:space-between"><span class="badge">${types[w.type]?.[0]||'骑行'}</span><span class="tiny">${duration(w.duration)} · 负荷 ${num(w.load)}</span></div><h3>${esc(w.name)}</h3>${miniChart(w)}<p>${esc(w.description||'自定义结构化训练')}</p><div class="actions"><button class="btn small" data-edit-workout="${esc(w.id)}">${icon('edit')}编辑</button><button class="btn small primary" data-schedule-workout="${esc(w.id)}">${icon('calendar')}安排训练</button>${['Ride','Workout'].includes(w.type)?`<button class="btn small" data-export-workout="${esc(w.id)}">${icon('download')}导出 ZWO</button>`:''}</div></article>`).join('')}</div>`:`<section class="panel">${empty('创建你的第一组训练','保存常用的耐力骑行、阈值间歇或跑步训练，随时安排到日历。',btn('新建训练','new-workout','plus',true),'library')}</section>`}`;}
function basicCompareView(){const available=state.activities.filter(a=>!a.planned&&a.type!=='Note'),[a,b]=state.compareIds.map(id=>state.activities.find(x=>x.id===id));const fields=[['类型',x=>types[x.type]?.[0]],['时间',x=>duration(x.duration)],['距离',x=>`${num(x.distance,1)} km`],['训练负荷',x=>num(x.load)],['平均功率',x=>x.power?`${num(x.power)} W`:'—'],['平均心率',x=>x.hr?`${num(x.hr)} bpm`:'—']];return heading('比较','选择两次活动，查看训练量与表现的差异。')+(available.length<2?`<section class="panel">${empty('至少需要两次已完成活动','导入或记录更多活动后，开始比较。',btn('导入活动','import','upload'),'compare')}</section>`:`<div class="compare-select">${[0,1].map(i=>`<select data-compare-select="${i}" aria-label="比较活动 ${i+1}"><option value="">选择${i?'第二':'第一'}次活动</option>${available.map(x=>`<option value="${esc(x.id)}" ${state.compareIds[i]===x.id?'selected':''}>${esc(x.date)} · ${esc(x.name)}</option>`).join('')}</select>`).join('')}</div>${a&&b?`<section class="panel"><table class="data-table"><thead><tr><th>指标</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th></tr></thead><tbody>${fields.map(([name,f])=>`<tr><td>${name}</td><td>${f(a)}</td><td>${f(b)}</td></tr>`).join('')}</tbody></table><div class="panel-body"><h3>功率时间序列</h3><p class="tooltip-hint">按各活动的累计时间对齐。</p>${compareChart(a,b)}</div></section>`:`<section class="panel">${empty('选择两次活动','上方分别选择一次活动，显示指标对照。','','compare')}</section>`}`);}
function alignedStreams(activities,key){const stop=Math.max(0,...activities.map(a=>a.streams?.at(-1)?.time||0)),domain=[0,stop];if(!stop)return {series:[],labels:[],domain};const series=activities.map((a,j)=>({...chartSeries(effectiveUIStreams(a),key,{stop,budget:3600}),color:['#8e67b1','#258d77'][j],area:activities.length===1}));return {series,domain,labels:series[0].times.map(t=>`${Math.round(t/60)}m`)};}
function compareChart(a,b){const d=alignedStreams([a,b],'power');if(!d.series.some(s=>s.values.some(Number.isFinite)))return empty('没有可比较的功率采样','两次活动的汇总指标仍可在上表比较。','','power');return `<div class="legend" style="padding:15px"><span><i style="background:#8e67b1"></i>${esc(a.name)}</span><span><i style="background:#258d77"></i>${esc(b.name)}</span></div>`+chart(d.series,{xLabels:d.labels,xDomain:d.domain,ylabel:'W',resolveRange:({start,stop,budget})=>({series:[a,b].map((ride,j)=>({...chartSeries(effectiveUIStreams(ride),'power',{start,stop,budget}),color:['#8e67b1','#258d77'][j]})),options:{xDomain:[start,stop]}})});}
function wellnessView(){return heading('健康状态','查看身体状态与健康指标趋势。',btn('记录状态','add-wellness','plus',true))+appleHealthTools.view()+wellnessTrendView({records:state.wellness,activities:state.activities,range:state.wellnessTrendRange||90,end:state.wellnessTrendEnd||today(),esc,chart,num,duration});}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function settingsView(){const s=state.settings;return heading('设置','管理运动员参数、本地数据与工作空间。')+`<form id="settings-form" class="panel"><section class="settings-section"><h3>运动员信息</h3><div class="form-grid">${field('姓名','name',s.name,'text','required maxlength="80"')}${field('体重 / kg','weight',s.weight,'number','min="20" max="300" step="0.1" required')}${field('功能性阈值功率 FTP / W','ftp',s.ftp,'number','min="30" max="1000" required')}${field('最大心率 / bpm','maxHr',s.maxHr,'number','min="80" max="250" required')}${field('静息心率 / bpm','restHr',s.restHr,'number','min="20" max="150" required')}</div></section><section class="settings-section"><h3>历史 FTP</h3><p class="section-caption">每行填写“生效日期 | FTP”，活动分析使用当天生效的数值。</p><label class="field">FTP 生效记录<textarea name="ftpHistory" rows="5" placeholder="2026-01-01 | 230&#10;2026-06-01 | 250">${esc((s.ftpHistory||[]).map(r=>`${r.date} | ${r.ftp}`).join('\n'))}</textarea></label></section><section class="settings-section"><h3>自动努力段识别</h3><div class="form-grid">${field('强度阈值 / % FTP','effortThresholdPct',s.effortThresholdPct??90,'number','min="30" max="300" step="0.1" required')}${field('累计高强度 / 秒','effortMinSeconds',s.effortMinSeconds??60,'number','min="5" max="3600" required')}${field('最多连接恢复 / 秒','effortRecoverySeconds',s.effortRecoverySeconds??15,'number','min="0" max="300" required')}</div><p class="tooltip-hint">自动努力段按活动当天的 FTP 与以下参数识别。</p></section><section class="settings-section"><h3>负荷模型</h3><div class="form-grid">${field('CTL 时间常数 / 天','ctlDays',s.ctlDays||42,'number','min="1" max="365" required')}${field('ATL 时间常数 / 天','atlDays',s.atlDays||7,'number','min="1" max="365" required')}${field('首条活动前的初始 CTL','initialCtl',s.initialCtl??0,'number','min="0" max="1000" step="0.1" required')}${field('首条活动前的初始 ATL','initialAtl',s.initialAtl??0,'number','min="0" max="1000" step="0.1" required')}</div><p class="tooltip-hint">设置 CTL、ATL 的衰减周期与训练起点。</p></section><div class="modal-foot"><span class="save-status" id="save-status"></span><button class="btn primary" type="submit">${icon('check')}保存设置</button></div></form><section class="panel" style="margin-top:20px"><div class="settings-section"><h3>本地数据</h3><p class="section-caption">导出完整备份可保存和迁移活动、训练计划、健康记录及设置。</p><div class="actions">${btn('导出完整备份','backup','download')}${btn('从备份恢复','restore','refresh')}${btn('导出活动 CSV','export-csv','download')}${btn('载入演示数据','demo','power')}${state.activities.some(a=>a.demo)||state.workouts.some(w=>w.demo)?btn('清除演示数据','clear-demo','trash'):''}</div></div></section><section class="panel" style="margin-top:20px"><div class="settings-section"><h3>关于 Cycle</h3><p class="section-caption">Cycle 1.0 · 正式版<br>你的骑行、训练与健康工作空间。<br>记录活动，分析表现，安排训练，积累每一次进步。</p>${btn('查看功能与计算说明','help','help')}</div></section>`;}
function renderPage(){const content=$('#content');if(!content)return;if(state.activityDetail){if(state.activities.some(a=>a.id===state.activityDetail.id))return activityTools.open(state.activityDetail.id,state.activityDetail.tab);activityTools.leave();}const views={calendar:calendarView,fitness:fitnessView,power:powerView,workouts:workoutsView,plans:planningTools.view,compare:compareView,wellness:wellnessView,workspace:workspaceTools.view,settings:settingsView};content.innerHTML=views[state.page]();bindPage();}
async function navigate(page){activityTools.leave();closeModal();state.page=page;try{if(page==='fitness'){state.fitness=await api(`/fitness?from=${addDays(today(),-89)}&to=${today()}`);}if(page==='power')await loadPower();if(page==='compare')await loadCompare();if(page==='wellness')state.wellness=await api('/wellness');if(page==='plans')await planningTools.load();shell();}catch(e){error(e);}}
let modalTrigger;
function modal(title,body,footer='',wide=false){modalTrigger=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;const el=$('.modal input,.modal select,.modal textarea,.modal button');el?.focus();}
function closeModal(){document.dispatchEvent(new Event('cycle-modal-close'));$('#modal-root').innerHTML='';modalTrigger?.focus?.();}
function activityForm(a={},defaultDate=today()){const editing=Boolean(a.id);modal(editing?'编辑活动':'添加活动',`<form id="activity-form"><div class="modal-content"><div class="form-grid"><label class="field full">活动名称<input name="name" value="${esc(a.name)}" required maxlength="200" placeholder="例如：晨间耐力骑行"></label>${field('日期','date',a.date||defaultDate,'date','required')}<label class="field">运动类型<select name="type">${Object.entries(types).map(([key,[label]])=>`<option value="${key}" ${a.type===key?'selected':''}>${label}</option>`).join('')}</select></label>${field('持续时间 / 分钟','duration',a.duration??60,'number','min="0" max="2160" step="any" required')}${field('距离 / km','distance',a.distance??0,'number','min="0" max="10000" step="any"')}${field('训练负荷','load',a.load??0,'number','min="0" max="10000" step="any"')}${field('平均功率 / W','power',a.power??'','number','min="0" max="5000" step="any"')}${field('平均心率 / bpm','hr',a.hr??'','number','min="0" max="300" step="any"')}<label class="field">器材<select name="gearId" id="activity-gear"><option value="">未分配</option>${state.gear.filter(g=>g.active||g.id===a.gearId).map(g=>`<option value="${esc(g.id)}" data-type="${g.type}" ${g.id===a.gearId?'selected':''}>${esc(g.name)} · ${types[g.type]?.[0]}${g.active?'':'（已停用）'}</option>`).join('')}</select></label><label class="check" style="align-self:center"><input type="checkbox" name="planned" ${a.planned?'checked':''}>这是一次训练计划</label><label class="check"><input type="checkbox" name="indoor" ${(a.indoor??(a.notes?.startsWith('FIT 经 Garmin 官方 SDK')&&a.notes.includes('虚拟骑行：路线、速度与海拔为训练平台记录')))?'checked':''}>室内 / 虚拟活动</label><label class="field full">训练内容与备注<textarea name="notes" maxlength="10000" placeholder="路线、体感、训练目标…">${esc(a.notes||'')}</textarea></label></div>${a.completionId||state.activities.some(x=>x.completionId===a.id)?'<p class="tooltip-hint">这条记录存在计划执行关联。修改运动类型或完成状态前，请先在周期计划执行页解除关联。</p>':''}${state.goals.some(g=>g.activityId===a.id)?'<p class="tooltip-hint">这条活动已关联比赛目标。修改运动类型或完成状态前，请先在目标编辑页解除关联。</p>':''}<p class="form-note">手动填写活动汇总与训练负荷。</p></div><div class="modal-foot"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary" type="submit">${icon('check')}保存${a.planned?'计划':'活动'}</button></div></form>`);const filterGear=()=>{const type=$('#activity-form [name=type]').value,select=$('#activity-gear');for(const option of select.options)option.hidden=Boolean(option.dataset.type&&option.dataset.type!==type);if(select.selectedOptions[0]?.hidden)select.value='';};$('#activity-form [name=type]').onchange=filterGear;filterGear();$('#activity-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),obj={...a,...Object.fromEntries(f),planned:f.has('planned'),indoor:f.has('indoor')};for(const k of ['duration','distance','load','power','hr']){obj[k]=f.get(k)===''?null:Number(f.get(k));}obj.gearId=f.get('gearId')||null;if(editing&&obj.load!==a.load)obj.loadMeta=null;try{await api(editing?`/activities/${a.id}`:'/activities',editing?'PUT':'POST',obj);closeModal();await refresh();if(editing&&state.activityDetail?.id===a.id)await activityTools.open(a.id,state.activityDetail.tab);else await navigate(state.page);toast('活动已保存');}catch(err){error(err);}};}
async function detail(id,tab='overview'){return activityTools.open(id,tab);}
function workoutForm(w={}){return workoutBuilder.open(w);}
function scheduleWorkout(id,date){const w=state.workouts.find(x=>x.id===id);if(!w)return;modal('安排训练',`<form id="schedule-form"><div class="modal-content"><h3>${esc(w.name)}</h3><p class="section-caption">${duration(w.duration)} · 参考负荷 ${num(w.load)}</p>${field('训练日期','date',date||today(),'date','required')}</div><div class="modal-foot"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary" type="submit">安排到日历</button></div></form>`);$('#schedule-form').onsubmit=async e=>{e.preventDefault();try{const day=new FormData(e.target).get('date');await api('/activities','POST',{name:w.name,type:w.type,date:day,duration:w.duration,load:w.load,planned:true,notes:w.description,intervals:w.intervals,distance:0});state.month=parseDate(day);closeModal();await refresh();await navigate('calendar');toast('训练已安排');}catch(err){error(err);}};}
function libraryModal(){modal('训练库',`<div class="modal-content">${state.workouts.length?state.workouts.map(w=>`<div class="panel" style="padding:16px;margin-bottom:12px"><div class="actions" style="justify-content:space-between"><div><h3>${esc(w.name)}</h3><p class="tiny">${duration(w.duration)} · 负荷 ${num(w.load)}</p></div><button class="btn small primary" data-schedule-workout="${esc(w.id)}">安排</button></div>${miniChart(w)}</div>`).join(''):empty('训练库还是空的','新建一组训练，保存你的常用训练结构。',btn('新建训练','new-workout'),'library')}</div>`,btn('新建训练','new-workout'));}
function wellnessForm(date=today()){const w=state.wellness.find(x=>x.date===date)||{};modal('记录健康状态',`<form id="wellness-form"><div class="modal-content"><div class="form-grid">${field('日期','date',w.date||date,'date','required')}${field('体重 / kg','weight',w.weight??'','number','min="20" max="300" step="0.1"')}${field('静息心率 / bpm','restHr',w.restHr??'','number','min="20" max="200"')}${field('HRV / ms','hrv',w.hrv??'','number','min="0" max="500" step="0.1"')}${field('睡眠 / 小时','sleep',w.sleep??'','number','min="0" max="24" step="0.1"')}${field('主观疲劳 / 1–5','fatigue',w.fatigue??'','number','min="1" max="5" step="1"')}<label class="field full">备注<textarea name="notes">${esc(w.notes||'')}</textarea></label></div></div><div class="modal-foot"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary" type="submit">保存状态</button></div></form>`);$('#wellness-form [name=date]').onchange=e=>wellnessForm(e.target.value);$('#wellness-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),obj=Object.fromEntries(f);for(const k of ['weight','restHr','hrv','sleep','fatigue'])obj[k]=f.get(k)===''?null:Number(f.get(k));try{await api('/wellness','POST',obj);state.wellness=await api('/wellness');closeModal();renderPage();toast('健康状态已保存');}catch(err){error(err);}};}
function confirmDialog(title,text,onConfirm){modal(title,`<div class="modal-content"><p style="line-height:1.9">${esc(text)}</p></div>`,`<button class="btn" data-action="close">取消</button><button class="btn primary" id="confirm-button">确认</button>`);$('#confirm-button').onclick=async()=>{const button=$('#confirm-button');button.disabled=true;button.textContent='处理中…';try{await onConfirm();}catch(e){button.disabled=false;button.textContent='确认';error(e);}};}
function help(){modal('使用指南',`<div class="modal-content"><div class="stack"><div><h3>记录每一次活动</h3><p class="section-caption">导入 FIT、CSV、GPX 或 TCX，也可以手动记录活动。FIT 支持功率、心率、速度、踏频、设备圈与计时暂停。</p></div><div><h3>分析训练表现</h3><p class="section-caption">活动详情集中展示轨迹、采样曲线、NP、IF、TSS、最佳努力和能力估测。拖选图表可放大局部，使用手动区间和功率修正深入分析。</p></div><div><h3>安排下一阶段</h3><p class="section-caption">在训练库建立结构化训练，组合周期计划并安排到日历。训练完成后关联实际活动，跟踪执行进度。</p></div><div><h3>积累健康趋势</h3><p class="section-caption">导入苹果健康 ZIP 或 XML，选择日期和指标后保存。每月上传完整导出，持续更新健康图表。</p></div><div><h3>保存你的工作空间</h3><p class="section-caption">活动、计划、健康数据和设置保存在本机。前往设置导出完整备份，用于保存或迁移。</p></div></div></div>`);}
async function loadDemo(){confirmDialog('载入演示数据','将添加带“演示”标记的活动与训练，现有记录会保留。建议先导出完整备份。',async()=>{await api('/demo','POST',{});closeModal();await refresh();state.month=new Date(2026,10,16,12);await navigate('calendar');toast('已载入演示数据，可在活动详情删除');});}
function options(){const old=$('#calendar-options');if(old){old.remove();return;}const el=document.createElement('div');el.id='calendar-options';el.className='popover';el.innerHTML=`<label><input type="checkbox" id="show-planned" ${state.showPlanned?'checked':''}>显示训练计划</label><label><input type="checkbox" id="compact-view" ${state.compact?'checked':''}>紧凑显示</label><label>运动类型 <select id="type-filter"><option value="all">全部运动</option>${Object.entries(types).map(([k,[v]])=>`<option value="${k}" ${state.type===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="tiny">筛选只影响活动显示；周汇总显示完整周。</div>`;$('.calendar-tools').append(el);$('#show-planned').onchange=e=>{state.showPlanned=e.target.checked;renderPage();};$('#compact-view').onchange=e=>{state.compact=e.target.checked;renderPage();};$('#type-filter').onchange=e=>{state.type=e.target.value;renderPage();};}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function backup(){const data=await api('/backup');download(`cycle-backup-${today()}.json`,JSON.stringify(data,null,2));toast('完整备份已导出');}
function exportCSV(){const cols=['name','type','date','duration','distance','load','power','hr','planned','notes'];const quote=v=>`"${String(v??'').replace(/"/g,'""')}"`;download(`cycle-activities-${today()}.csv`,'\ufeff'+[cols.join(','),...state.activities.map(a=>cols.map(k=>quote(a[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast('活动 CSV 已导出');}
async function importFile(file){if(file.size>25*1024*1024)throw new Error('单个文件请小于 25 MB');toast(`正在导入 ${file.name}…`);const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const payload={filename:file.name,content:btoa(binary)};let result;try{result=await api('/import','POST',payload);}catch(e){if(e.code==='DUPLICATE_IMPORT'&&/\.fit$/i.test(file.name)){return confirmDialog('补充 FIT 骑行详情','此文件已导入。是否补充设备汇总、温度等新支持的字段？原活动与编辑内容将保留。',async()=>{const enriched=await api('/import','POST',{...payload,enrichExisting:true});await refresh();if(state.activityDetail)renderPage();else await navigate('calendar');toast(`已补充 ${enriched.count} 条活动的 FIT 详情`);});}throw e;}await refresh();if(result.activities?.length){const latest=[...result.activities].sort((a,b)=>b.date.localeCompare(a.date))[0];state.month=parseDate(latest.date);}await navigate('calendar');toast(result.message||`导入完成${result.count!==undefined?` · ${result.count} 条活动`:''}`);}
function bindPage(){if($('[data-ftp-activity]'))$('[data-ftp-activity]').onchange=async e=>{state.ftpActivityId=e.target.value;try{await loadPower();renderPage();}catch(err){error(err);}};if($('#wellness-trend-range'))$('#wellness-trend-range').onchange=e=>{state.wellnessTrendRange=Number(e.target.value);renderPage();};if($('#wellness-trend-end'))$('#wellness-trend-end').onchange=e=>{if(!e.target.value)return;if(!e.target.checkValidity())return toast('请选择 1901–2200 年的有效日期');state.wellnessTrendEnd=e.target.value;renderPage();};if($('#power-range'))$('#power-range').onchange=async e=>{state.powerRange=e.target.value;if(state.powerRange==='custom'){state.powerFrom=state.powerFrom||addDays(today(),-89);state.powerTo=state.powerTo||today();}try{await loadPower();renderPage();}catch(err){error(err);}};if($('#power-type'))$('#power-type').onchange=async e=>{state.powerType=e.target.value;try{await loadPower();renderPage();}catch(err){error(err);}};if($('#calendar-search'))$('#calendar-search').oninput=e=>{state.query=e.target.value;$('#calendar-body').innerHTML=state.view==='calendar'?calendarGrid():activityTable(filtered(monthActivities()));};if($('#fitness-range'))$('#fitness-range').onchange=async e=>{const days=Number(e.target.value);try{state.fitness=await api(`/fitness?from=${addDays(today(),1-days)}&to=${today()}`);const chartEl=$('.chart-wrap');chartEl.innerHTML=fitnessChart(state.fitness);}catch(err){error(err);}};if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{f.ftpHistory=String(f.ftpHistory||'').split('\n').map(l=>l.trim()).filter(Boolean).map((l,i)=>{const m=/^(\d{4}-\d{2}-\d{2})\s*\|\s*(\d+(?:\.\d+)?)$/.exec(l);if(!m)throw Error(`历史 FTP 第 ${i+1} 行格式无效，请填写 日期 | FTP`);return {date:m[1],ftp:Number(m[2])};});for(const k of Object.keys(f))if(!['name','ftpHistory'].includes(k))f[k]=Number(f[k]);state.settings=await api('/settings','PUT',f);shell();$('#save-status').textContent='设置已保存';toast('设置已保存');}catch(err){error(err);}};}

function effectiveUIStreams(a){a=elevationActivity(a);const m=new Map((a.powerCorrections||[]).map(c=>[c.time,c.power]));return (a.streams||[]).map(s=>{if(!m.has(s.time)&&s.timerActive!==false)return s;const c={...s};if(s.timerActive===false){delete c.power;delete c.hr;delete c.cadence;delete c.speed;return c;}if(m.get(s.time)===null)delete c.power;else c.power=m.get(s.time);return c;});}
function powerQuery(){const q=new URLSearchParams();let from='',to='';if(state.powerRange==='42') {from=addDays(today(),-41);to=today();}else if(state.powerRange==='90'){from=addDays(today(),-89);to=today();}else if(state.powerRange==='season'){from=today().slice(0,4)+'-01-01';to=today();}else if(state.powerRange==='last-season'){const y=Number(today().slice(0,4))-1;from=y+'-01-01';to=y+'-12-31';}else if(state.powerRange==='custom'){from=state.powerFrom;to=state.powerTo;}if(from)q.set('from',from);if(to)q.set('to',to);if(state.powerType!=='all')q.set('type',state.powerType);return q.toString();}
async function loadPower(){state.power=await api('/power?'+powerQuery());const candidates=state.power.estimateActivities||[];if(!candidates.some(a=>a.id===state.ftpActivityId))state.ftpActivityId=candidates[0]?.id||null;state.power.singleEstimate=state.ftpActivityId?await api(`/activities/${encodeURIComponent(state.ftpActivityId)}/analysis`):null;}
async function loadCompare(){const ids=[...new Set(state.compareIds.filter(Boolean))];const data=await Promise.all(ids.map(id=>api('/activities/'+id+'/analysis')));state.compareAnalysis=Object.fromEntries(ids.map((id,i)=>[id,data[i].summary]));}
async function reviewFtp(activity,suggestion){state.settings=await api('/settings');const fresh=await api(`/activities/${encodeURIComponent(activity.id)}/analysis`);suggestion=fresh.estimates?.updateSuggestion;if(!suggestion)return toast('设置或活动数据已变化，当前没有适用的更新提示');await navigate('settings');const input=$('#settings-form [name=ftp]'),history=$('#settings-form [name=ftpHistory]');input.value=suggestion.value;const date=today(),rows=(state.settings.ftpHistory||[]).filter(r=>r.date!==date);rows.push({date,ftp:suggestion.value});history.value=rows.sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`${r.date} | ${r.ftp}`).join('\n');const note=document.createElement('p');note.className='ftp-review-note';note.textContent=`${activity.name}（${activity.date}）· ${suggestion.label} ${suggestion.value} W。核对后保存，将更新当前 FTP 及今天的生效记录。`;$('#settings-form').prepend(note);$('#save-status').textContent='参考值已填入，核对后点击保存设置';input.focus();input.scrollIntoView({block:'center'});}
function singleActivityEstimateView(){const candidates=state.power.estimateActivities||[],a=state.activities.find(a=>a.id===state.ftpActivityId),data=state.power.singleEstimate;return `<section class="panel ftp-activity-picker"><div class="panel-body"><label class="field">选择要估测 FTP 的活动<select data-ftp-activity aria-label="FTP 估测活动"><option value="" ${a?'disabled':''}>${a?'选择活动':'筛选范围内没有已完成的真实骑行'}</option>${candidates.map(c=>`<option value="${esc(c.id)}" ${a?.id===c.id?'selected':''}>${esc(c.date+' · '+c.name)}</option>`).join('')}</select></label><p class="tiny">选择一次骑行查看能力估测，功率曲线展示当前筛选范围的最佳表现。</p></div></section>`+(a&&data?performanceCard(data.bestEfforts,state.settings,{esc,num,activity:a,estimates:data.estimates}):'');}
function powerView(){const filters='<div class="power-filters"><label>时间范围<select id="power-range" aria-label="功率时间范围">'+[['all','全部时间'],['42','近 42 天'],['90','近 90 天'],['season','本赛季（自然年）'],['last-season','上赛季（自然年）'],['custom','自定义日期']].map(([k,n])=>'<option value="'+k+'" '+(state.powerRange===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>运动<select id="power-type" aria-label="功率运动类型"><option value="all">全部运动</option>'+Object.entries(types).filter(([k])=>k!=='Note').map(([k,[n]])=>'<option value="'+k+'" '+(state.powerType===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label>'+(state.powerRange==='custom'?'<label>开始<input type="date" id="power-from" aria-label="功率开始日期" value="'+esc(state.powerFrom)+'"></label><label>结束<input type="date" id="power-to" aria-label="功率结束日期" value="'+esc(state.powerTo)+'"></label><button class="btn small" data-action="apply-power-filter">应用日期</button>':'')+'<span class="tiny">使用已完成活动与已保存的功率修正 · 分区按活动生效 FTP</span></div>';const curve=state.power.curve||[];return basicPowerView().replace('<div class="summary-strip">',filters+singleActivityEstimateView()+'<div class="summary-strip">')+(curve.length?'<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>最佳努力来源</h2><span class="tiny">点击来源打开完整活动分析</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>持续时间</th><th>最佳均值</th><th>W/kg</th><th>来源活动</th></tr></thead><tbody>'+curve.map(c=>{const a=state.activities.find(x=>x.id===c.activityId);return '<tr><td>'+(c.seconds<60?c.seconds+'s':duration(c.seconds/60))+'</td><td class="purple">'+num(c.watts)+' W</td><td>'+num(c.watts/state.settings.weight,2)+'</td><td><button class="name-cell" data-activity="'+esc(c.activityId)+'">'+esc(a? a.date+' · '+a.name:'查看活动')+'</button></td></tr>';}).join('')+'</tbody></table></div></section>':'');}
function compareView(){const a=state.compareAnalysis[state.compareIds[0]],b=state.compareAnalysis[state.compareIds[1]];if(!a||!b)return basicCompareView();const fields=[['分析 FTP','ftp',' W',0],['标准化功率 NP','normalizedPower',' W',0],['强度系数 IF','intensityFactor','',2],['计算负荷 TSS','tss','',1],['变异指数 VI','variabilityIndex','',2],['机械功','workKj',' kJ',1],['功率/心率解耦','decoupling','%',1]];const v=(s,key,u,d)=>s[key]===null?'—':num(s[key],d)+u;return basicCompareView()+'<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>采样分析对照</h2></div><table class="data-table"><thead><tr><th>指标</th><th>第一活动</th><th>第二活动</th></tr></thead><tbody>'+fields.map(([n,k,u,d])=>'<tr><td>'+n+'</td><td>'+v(a,k,u,d)+'</td><td>'+v(b,k,u,d)+'</td></tr>').join('')+'</tbody></table><p class="panel-body tiny">基于活动采样计算 NP、IF、TSS 与功率表现。</p></section>';}

const workspaceTools=createWorkspaceTools({state,api,esc,icon,num,duration,modal,closeModal,toast,refresh,renderPage,confirmDialog,field,today,heading});
const workoutBuilder=createWorkoutBuilder({state,api,esc,icon,num,modal,closeModal,toast,refresh,renderPage,download});
const planningTools=createPlanningTools({state,api,esc,icon,num,duration,modal,closeModal,toast,refresh,renderPage,confirmDialog,navigate,heading,empty,field,today,parseDate});
const appleHealthTools=createAppleHealthTools({api,esc,num,chart,modal,closeModal,toast,state,renderPage});
const activityTools=createActivityTools({state,api,esc,icon,num,duration,modal,closeModal,toast,refresh,renderPage,confirmDialog,chart,effectiveUIStreams,reviewFtp});
const actions={'apply-power-filter':async()=>{const from=$('#power-from').value,to=$('#power-to').value;if(!from||!to||from>to)return toast('请选择有效的起止日期');state.powerFrom=from;state.powerTo=to;await loadPower();renderPage();},add:()=>activityForm(),import:()=>$('#file-input').click(),close:closeModal,prev:()=>{state.month.setMonth(state.month.getMonth()-1,1);renderPage();},next:()=>{state.month.setMonth(state.month.getMonth()+1,1);renderPage();},today:()=>{state.month=new Date();renderPage();},demo:loadDemo,'demo-info':()=>toast('演示活动带有紫色标记，可在活动详情删除；默认数据库为空。'),'new-workout':()=>workoutForm(),library:libraryModal,options,backup,restore:()=>$('#backup-input').click(),'export-csv':exportCSV,help,'add-wellness':()=>wellnessForm(),'clear-demo':()=>confirmDialog('清除演示数据','将删除带演示标记的活动与训练库模板，保留你自己创建和导入的记录。',async()=>{await api('/demo','DELETE');closeModal();await refresh();await navigate(state.page);toast('演示记录已清除');}),menu:()=>$('.sidebar').classList.toggle('open'),dark:()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);localStorage.setItem('cycle-dark',String(state.dark));}};
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-activity]');if(!b)return;try{if(b.dataset.nav)return await navigate(b.dataset.nav);if(b.dataset.action){await actions[b.dataset.action]?.();return;}if(b.dataset.addDate)return activityForm({},b.dataset.addDate);if(b.dataset.view){state.view=b.dataset.view;renderPage();return;}if(b.dataset.activity)return detail(b.dataset.activity);if(b.dataset.detailTab)return detail(b.dataset.id,b.dataset.detailTab);if(b.dataset.editActivity)return activityForm(state.activities.find(a=>a.id===b.dataset.editActivity));if(b.dataset.copyActivity){const a={...state.activities.find(x=>x.id===b.dataset.copyActivity)};delete a.id;delete a.demo;delete a.importHash;delete a.importSessionIndex;delete a.fitSummary;delete a.fitDevices;delete a.elevationCorrection;delete a.weather;delete a.startedAt;delete a.ftpEstimateMethod;a.name+='（副本）';a.streams=[];a.segments=[];a.laps=[];a.powerCorrections=[];delete a.analysisMode;delete a.loadMeta;delete a.planOrigin;delete a.completionId;if(a.gearId&&!state.gear.some(g=>g.id===a.gearId&&g.active))delete a.gearId;return activityForm(a);}if(b.dataset.completeActivity){const a=state.activities.find(x=>x.id===b.dataset.completeActivity);return confirmDialog('标记为已完成','该操作使用计划数值生成已完成记录。请在编辑页面核对实际时间与训练负荷。',async()=>{await api(`/activities/${a.id}`,'PUT',{...a,planned:false});closeModal();await refresh();renderPage();toast('已标记完成，请按实际情况修正记录');});}if(b.dataset.deleteActivity){const id=b.dataset.deleteActivity;return confirmDialog('删除活动','确认删除这条活动及其采样数据？此操作不可撤销。',async()=>{await api(`/activities/${id}`,'DELETE');closeModal();await refresh();renderPage();toast('活动已删除');});}if(b.dataset.editWorkout)return workoutForm(state.workouts.find(w=>w.id===b.dataset.editWorkout));if(b.dataset.scheduleWorkout)return scheduleWorkout(b.dataset.scheduleWorkout);if(b.dataset.deleteWorkout){const id=b.dataset.deleteWorkout;return confirmDialog('删除训练','仅删除训练库模板，已安排到日历的计划会保留。',async()=>{await api(`/workouts/${id}`,'DELETE');closeModal();await refresh();renderPage();toast('训练已删除');});}if(b.dataset.wellness)return wellnessForm(b.dataset.wellness);}catch(err){error(err);}});
document.addEventListener('change',e=>{if(e.target.dataset.compareSelect!==undefined){state.compareIds[Number(e.target.dataset.compareSelect)]=e.target.value;loadCompare().then(renderPage).catch(error);}});
document.addEventListener('dblclick',e=>{const day=e.target.closest('[data-date]');if(day&&!e.target.closest('button'))activityForm({},day.dataset.date);});
document.addEventListener('dragstart',e=>{const a=e.target.closest('[data-activity]'),w=e.target.closest('[data-workout]');if(a)e.dataTransfer.setData('text/plain',JSON.stringify({activity:a.dataset.activity}));if(w)e.dataTransfer.setData('text/plain',JSON.stringify({workout:w.dataset.workout}));});
document.addEventListener('dragover',e=>{const day=e.target.closest('[data-date]');if(day){e.preventDefault();day.classList.add('dragover');e.dataTransfer.dropEffect='move';}});
document.addEventListener('dragleave',e=>{const day=e.target.closest('[data-date]');if(day&&!day.contains(e.relatedTarget))day.classList.remove('dragover');});
document.addEventListener('dragend',()=>$$('.dragover').forEach(el=>el.classList.remove('dragover')));
document.addEventListener('drop',async e=>{const day=e.target.closest('[data-date]');if(!day)return;e.preventDefault();try{const data=JSON.parse(e.dataTransfer.getData('text/plain'));if(data.workout)return scheduleWorkout(data.workout,day.dataset.date);const a=state.activities.find(x=>x.id===data.activity);if(!a)return;await api(`/activities/${a.id}`,'PUT',{...a,date:day.dataset.date});await refresh();renderPage();toast('活动日期已更新');}catch(err){error(err);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#calendar-options')?.remove();$('.sidebar')?.classList.remove('open');}if(e.key==='Tab'&&$('.modal')){const els=$$('button,input,textarea,select,a[href]', $('.modal')).filter(el=>!el.disabled&&el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#file-input').onchange=async e=>{const files=[...e.target.files];e.target.value='';for(const file of files)try{await importFile(file);}catch(err){error(err);}};
$('#backup-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>256*1024*1024)throw new Error('请选择 256 MB 以内的备份文件');const data=JSON.parse(await file.text());confirmDialog('从备份恢复','恢复将替换现有本地数据。请先保存当前备份，再确认继续。',async()=>{await api('/restore','POST',data);closeModal();await refresh();if(state.activities.length)state.month=parseDate([...state.activities].sort((a,b)=>b.date.localeCompare(a.date))[0].date);await navigate('calendar');toast('备份已恢复');});}catch(err){error(err);}};
try{await refresh();shell();}catch(e){$('#app').innerHTML=`<div class="empty"><strong>本地服务连接失败</strong><p>${esc(e.message)}</p><p>请重新启动 Cycle。</p><button class="btn" id="retry-connect">重试</button></div>`;$('#retry-connect').onclick=()=>location.reload();}
